function fail(field, message) {
    var e = new Error(message);
    e.field = field;
    return e;
}

function checkDirection(direction) {
    if (direction !== 's2t' && direction !== 't2s') {
        throw fail('direction', "转换方向非法：只接受 's2t'（简→繁）或 't2s'（繁→简）");
    }
}

/* ================= convertText ================= */

/* 短语表最长匹配优先，再单字表逐字；不在表字符原样保留。
 * convertedCount：短语命中消耗的全部字数＋单字表命中字数（原样保留的不计）；
 * phraseHits：短语命中次数；totalChars：输入码位数。
 * 简→繁时，未被短语覆盖的一字多繁字记入 ambiguous（位置／原字／本次所选／全部候选），
 * 供页面标注并提示人工校对；繁→简无歧义，ambiguous 恒为空数组。 */
function convertText(input, direction) {
    checkDirection(direction);
    if (typeof input !== 'string') throw fail('input', '输入须为字符串');
    if (input === '') throw fail('input', '输入为空：请粘贴要转换的文本');
    var chars = Array.from(input);
    if (chars.length > MAX_INPUT) {
        throw fail('input', '输入超过 ' + MAX_INPUT + ' 字符上限（实得 ' + chars.length + ' 字符），请拆分后粘贴');
    }
    var s2t = direction === 's2t';
    var map = s2t ? S2T_MAP : T2S_MAP;
    var phrases = s2t ? PHRASE_S2T : PHRASE_T2S;
    var out = [];
    var convertedCount = 0;
    var phraseHits = 0;
    var ambiguous = [];
    var i = 0;
    while (i < chars.length) {
        var matched = null;
        var matchedLen = 0;
        var maxLen = Math.min(MAX_PHRASE_LEN, chars.length - i);
        for (var L = maxLen; L >= 2; L--) {
            var slice = chars.slice(i, i + L).join('');
            if (Object.prototype.hasOwnProperty.call(phrases, slice)) {
                matched = phrases[slice];
                matchedLen = L;
                break;
            }
        }
        if (matched !== null) {
            out.push(matched);
            convertedCount += matchedLen;
            phraseHits++;
            i += matchedLen;
            continue;
        }
        var ch = chars[i];
        if (Object.prototype.hasOwnProperty.call(map, ch)) {
            out.push(map[ch]);
            convertedCount++;
            if (s2t && Object.prototype.hasOwnProperty.call(AMBIGUOUS, ch)) {
                ambiguous.push({ pos: i, char: ch, chosen: map[ch], candidates: AMBIGUOUS[ch].slice() });
            }
        } else {
            out.push(ch);
            if (s2t && Object.prototype.hasOwnProperty.call(AMBIGUOUS, ch)) {
                ambiguous.push({ pos: i, char: ch, chosen: ch, candidates: AMBIGUOUS[ch].slice() });
            }
        }
        i++;
    }
    return {
        text: out.join(''),
        convertedCount: convertedCount,
        phraseHits: phraseHits,
        totalChars: chars.length,
        ambiguous: ambiguous
    };
}

function simplifiedToTraditional(input) {
    return convertText(input, 's2t').text;
}

function traditionalToSimplified(input) {
    return convertText(input, 't2s').text;
}

/* 单字转换：非单字符（空串／多字／非字符串）抛错 err.field='ch'；
 * 不在表字符原样返回。 */
function convertChar(ch, direction) {
    checkDirection(direction);
    if (typeof ch !== 'string' || Array.from(ch).length !== 1) {
        throw fail('ch', 'convertChar 只接受单个字符');
    }
    var map = direction === 's2t' ? S2T_MAP : T2S_MAP;
    return Object.prototype.hasOwnProperty.call(map, ch) ? map[ch] : ch;
}

